        ?string $relation = null,
        ?string $release = null,
        ?array $sortBy = null,
        ?\Rafflesia\RequestOptions $options = null,
    ): \Rafflesia\Resource\EnvelopeVariantMapData {
        $body = array_filter([
            'allow_network' => $allowNetwork,
            'chain' => $chain,
            'database' => $database,
            'mutations' => $mutations,
            'output_format' => $outputFormat?->value,
            'output_relation' => $outputRelation,
            'partition_by' => $partitionBy,
            'preview_limit' => $previewLimit,
            'relation' => $relation,
            'release' => $release,
            'sort_by' => $sortBy,
            'structure_id' => $structureId,
            'target_id' => $targetId,
        ], fn ($v) => $v !== null);
        $response = $this->client->request(
            method: 'POST',
            path: 'v1/proteins/variants/map',
            body: $body,
            options: $options,
        );
        return EnvelopeVariantMapData::fromArray($response);
    }

    /**
     * @param array<string>|null $mutations Mutation strings in the form WILDTYPE_AA + POSITION (1-based) + MUTANT_AA, e.g. M1775R or Y1853X. X (or *) as the mutant denotes a stop/nonsense change.
     * @return \Rafflesia\Resource\EnvelopeVariantParseData
     * @throws \Rafflesia\Exception\RafflesiaException
     */
    public function variantsParse(
        ?array $mutations,
        ?\Rafflesia\RequestOptions $options = null,
    ): \Rafflesia\Resource\EnvelopeVariantParseData {
        $body = [
            'mutations' => $mutations,
        ];
        $response = $this->client->request(
            method: 'POST',
            path: 'v1/proteins/variants/parse',
            body: $body,
            options: $options,
        );
        return EnvelopeVariantParseData::fromArray($response);
    }
}
